// tb/v3/tb_ch10_voicing.v
// Cycle-accurate, bit-exact testbench for rtl/v3/ch10_voicing.v
// Compatible with iverilog -g2012 -Wall
//
// Verification protocol:
// - Reads streaming transaction vectors generated by Python twin (verify_v3/ch10_twin.py)
// - Verifies shift-add constants, 54-bit signed products, strict comparator (LHS > RHS),
//   silence shortcuts (R0=0, LP=0, GP=0, !cand_found), and Q12.4 F0 gating.
// - 2-phase sampling convention:
//     * Inputs driven at @(negedge clk)
//     * Registered outputs checked at @(posedge clk); #1
// - Strict loop condition, counts all errors, reports total
// - Total vectors: 641 transactions, exactly 1408 simulation cycles.

`timescale 1ns / 1ps

module tb_ch10_voicing;

    localparam integer EXPECTED_CYCLES = 1408;

    // Clock generation (50 MHz, 20 ns period)
    reg clk = 0;
    always #10 clk = ~clk;

    // DUT inputs
    reg               rst_n;
    reg               in_valid;
    reg  [15:0]       in_f0_raw;
    reg  signed [27:0] in_sc;
    reg  [26:0]       in_r0n;
    reg               in_cand_found;
    reg  [15:0]       in_lp;
    reg  [15:0]       in_gp;

    // DUT outputs
    wire              out_valid;
    wire [15:0]       out_f0;
    wire              out_voiced;
    wire signed [53:0] out_lhs;
    wire signed [53:0] out_rhs;

    // Instantiate DUT
    ch10_voicing dut (
        .clk           (clk),
        .rst_n         (rst_n),
        .in_valid      (in_valid),
        .in_f0_raw     (in_f0_raw),
        .in_sc         (in_sc),
        .in_r0n        (in_r0n),
        .in_cand_found (in_cand_found),
        .in_lp         (in_lp),
        .in_gp         (in_gp),
        .out_valid     (out_valid),
        .out_f0        (out_f0),
        .out_voiced    (out_voiced),
        .out_lhs       (out_lhs),
        .out_rhs       (out_rhs)
    );

    // Testbench tracking variables
    integer stim_fd;
    integer exp_fd;
    integer cycle_idx;
    integer errors;

    // Stimulus record variables
    integer stim_rst_n;
    integer stim_in_vld;
    integer stim_in_f0;
    reg signed [63:0] stim_in_sc;
    integer stim_in_r0n;
    integer stim_in_cand;
    integer stim_in_lp;
    integer stim_in_gp;

    // Expected record variables
    integer exp_out_vld;
    integer exp_out_f0;
    integer exp_out_voiced;
    reg signed [63:0] exp_out_lhs;
    reg signed [63:0] exp_out_rhs;

    initial begin
        rst_n         = 0;
        in_valid      = 0;
        in_f0_raw     = 16'd0;
        in_sc         = 28'sd0;
        in_r0n        = 27'd0;
        in_cand_found = 0;
        in_lp         = 16'd0;
        in_gp         = 16'd0;
        cycle_idx     = 0;
        errors        = 0;

        // Open stimulus file
        stim_fd = $fopen("verify_v3/tb_ch10_voicing_stim.txt", "r");
        if (stim_fd == 0) stim_fd = $fopen("tb_ch10_voicing_stim.txt", "r");
        if (stim_fd == 0) begin
            $display("[FAIL] Cannot open tb_ch10_voicing_stim.txt");
            $finish;
        end

        // Open expected file
        exp_fd = $fopen("verify_v3/tb_ch10_voicing_expected.txt", "r");
        if (exp_fd == 0) exp_fd = $fopen("tb_ch10_voicing_expected.txt", "r");
        if (exp_fd == 0) begin
            $display("[FAIL] Cannot open tb_ch10_voicing_expected.txt");
            $finish;
        end

        $display("=== STARTING CH10 VOICING UNIT VERIFICATION ===");

        @(negedge clk);

        while ($fscanf(stim_fd, "%d %d %d %d %d %d %d %d\n",
                       stim_rst_n, stim_in_vld, stim_in_f0,
                       stim_in_sc, stim_in_r0n, stim_in_cand,
                       stim_in_lp, stim_in_gp) == 8 &&
               $fscanf(exp_fd, "%d %d %d %d %d\n",
                       exp_out_vld, exp_out_f0, exp_out_voiced,
                       exp_out_lhs, exp_out_rhs) == 5) begin

            // 1. Drive inputs during clock low phase
            rst_n         = (stim_rst_n != 0) ? 1'b1 : 1'b0;
            in_valid      = (stim_in_vld != 0) ? 1'b1 : 1'b0;
            in_f0_raw     = stim_in_f0[15:0];
            in_sc         = stim_in_sc[27:0];
            in_r0n        = stim_in_r0n[26:0];
            in_cand_found = (stim_in_cand != 0) ? 1'b1 : 1'b0;
            in_lp         = stim_in_lp[15:0];
            in_gp         = stim_in_gp[15:0];

            // 2. Wait for rising edge and sample registered outputs after #1
            @(posedge clk);
            #1;

            if (out_valid !== ((exp_out_vld != 0) ? 1'b1 : 1'b0)) begin
                $display("[FAIL] Cycle %0d: out_valid mismatch DUT=%b EXP=%b",
                         cycle_idx, out_valid, exp_out_vld != 0);
                errors = errors + 1;
            end

            if (out_valid) begin
                if (out_voiced !== ((exp_out_voiced != 0) ? 1'b1 : 1'b0)) begin
                    $display("[FAIL] Cycle %0d: out_voiced mismatch DUT=%b EXP=%b",
                             cycle_idx, out_voiced, exp_out_voiced != 0);
                    errors = errors + 1;
                end

                if (out_f0 !== exp_out_f0[15:0]) begin
                    $display("[FAIL] Cycle %0d: out_f0 mismatch DUT=%0d EXP=%0d",
                             cycle_idx, out_f0, exp_out_f0);
                    errors = errors + 1;
                end

                if (out_lhs !== exp_out_lhs[53:0]) begin
                    $display("[FAIL] Cycle %0d: out_lhs mismatch DUT=%0d EXP=%0d",
                             cycle_idx, $signed(out_lhs), $signed(exp_out_lhs));
                    errors = errors + 1;
                end

                if (out_rhs !== exp_out_rhs[53:0]) begin
                    $display("[FAIL] Cycle %0d: out_rhs mismatch DUT=%0d EXP=%0d",
                             cycle_idx, $signed(out_rhs), $signed(exp_out_rhs));
                    errors = errors + 1;
                end
            end

            cycle_idx = cycle_idx + 1;
            @(negedge clk);
        end

        $fclose(stim_fd);
        $fclose(exp_fd);

        if (cycle_idx != EXPECTED_CYCLES) begin
            $display("[FAIL] Read %0d cycles, expected %0d", cycle_idx, EXPECTED_CYCLES);
            errors = errors + 1;
        end

        $display("=== Total comparison errors: %0d ===", errors);

        if (errors == 0) begin
            $display("[PASS] All %0d cycles matched bit-for-bit with Python twin!", cycle_idx);
        end else begin
            $display("[FAIL] Total comparison errors: %0d", errors);
        end

        $finish;
    end

endmodule
